// ① JS 模拟版：单线程事件循环下，函数体即原子单元（对应 Redis Lua 的执行语义）
class SeckillStock {
  constructor(total) {
    this.stock = total;
    this.boughtUsers = new Set(); // 一人一单标记
  }

  deduct(userId) {
    if (this.boughtUsers.has(userId)) return false; // 重复购买
    if (this.stock <= 0) return false;              // 库存不足
    this.stock -= 1;
    this.boughtUsers.add(userId);
    return true;
  }
}

// 对应的 Redis Lua 脚本（生产可用，KEYS[1]=库存key，KEYS[2]=已购用户集合）
const luaScript = `
if redis.call('sismember', KEYS[2], ARGV[1]) == 1 then
  return 0  -- 重复购买
end
local stock = tonumber(redis.call('get', KEYS[1]))
if stock == nil or stock <= 0 then
  return 0  -- 库存不足
end
redis.call('decr', KEYS[1])
redis.call('sadd', KEYS[2], ARGV[1])
return 1      -- 成功
`;

