// ③ 并发测试：1000 用户抢 100 件
async function runTest() {
  const seckill = new SeckillStock(100);
  const users = Array.from({ length: 1000 }, (_, i) => 'u' + i);
  const results = await Promise.all(
    users.map((u) => new Promise((resolve) => {
      setImmediate(() => resolve({ user: u, ok: seckill.deduct(u) }));
    }))
  );
  const success = results.filter((r) => r.ok);
  console.log('成功单数:', success.length);            // 100，不超卖
  console.log('剩余库存:', seckill.stock);             // 0
  console.log('成功用户去重后:', new Set(success.map((r) => r.user)).size); // 100，无重复
  // 同一用户重复尝试
  console.log('同用户二次抢购:', seckill.deduct(success[0].user)); // false
}
runTest();
